.darma-loader-darma-b7-slinky-spring { --accent: var(--loader-color, #d946ef); width: calc(var(--loader-size, 80px) * .6); height: var(--loader-size, 80px); display: flex; flex-direction: column; align-items: center; justify-content: center; }
.darma-loader-darma-b7-slinky-spring span { width: 100%; height: calc(var(--loader-size, 80px) * .08); border: calc(var(--loader-size, 80px) * .028) solid var(--accent); border-radius: 50%; margin: calc(var(--loader-size, 80px) * .012) 0; animation: darma-loader-darma-b7-slinky-spring-coil calc(var(--loader-speed, 1s) * 1.2) ease-in-out infinite; }
.darma-loader-darma-b7-slinky-spring span:nth-child(1) { animation-delay: 0s; }
.darma-loader-darma-b7-slinky-spring span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * .1); }
.darma-loader-darma-b7-slinky-spring span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * .2); }
.darma-loader-darma-b7-slinky-spring span:nth-child(4) { animation-delay: calc(var(--loader-speed, 1s) * .3); }
.darma-loader-darma-b7-slinky-spring span:nth-child(5) { animation-delay: calc(var(--loader-speed, 1s) * .4); }
@keyframes darma-loader-darma-b7-slinky-spring-coil { 0%, 100% { transform: scaleX(.5); opacity: .4; } 50% { transform: scaleX(1); opacity: 1; } }

